-- Kos Manager initial schema. Apply only in the dedicated new project.
create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, phone text, created_at timestamptz default now());
create table public.properties(id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id), property_name text not null, address text, phone text, description text, is_active boolean not null default true, created_at timestamptz not null default now(), unique(owner_id,property_name));
create table public.rooms(id uuid primary key default gen_random_uuid(), owner_id uuid not null default auth.uid() references auth.users(id), property_id uuid not null references public.properties(id), room_name text not null, floor_label text, room_type text, monthly_price numeric(14,2) not null default 0 check(monthly_price>=0), area_size numeric(8,2), description text, status text not null default 'available' check(status in('available','occupied','maintenance','inactive')), created_at timestamptz not null default now(), unique(property_id,room_name));
create table public.amenities(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,unique(owner_id,name));
create table public.room_amenities(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),room_id uuid not null references public.rooms(id),amenity_id uuid not null references public.amenities(id),extra_fee numeric(14,2) not null default 0 check(extra_fee>=0),fee_frequency text not null default 'monthly',unique(room_id,amenity_id));
create table public.room_photos(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),room_id uuid not null references public.rooms(id),storage_path text not null,caption text);
create table public.tenants(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),full_name text not null,phone text,identity_number text,address text,emergency_contact_name text,emergency_contact_phone text,photo_path text,notes text,is_active boolean not null default true,created_at timestamptz not null default now());
create table public.tenant_documents(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),tenant_id uuid not null references public.tenants(id),document_type text not null check(document_type in('ktp_front','ktp_back','kk','other')),storage_path text not null,original_filename text,created_at timestamptz not null default now());
create table public.rental_agreements(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),tenant_id uuid not null references public.tenants(id),room_id uuid not null references public.rooms(id),start_date date not null,end_date date,rent_amount numeric(14,2) not null check(rent_amount>=0),billing_cycle text not null default 'monthly' check(billing_cycle in('daily','weekly','monthly','yearly','custom')),billing_interval integer not null default 1 check(billing_interval>0),due_day integer check(due_day between 1 and 31),custom_terms jsonb not null default '{}'::jsonb,status text not null default 'active',contract_file_path text,created_at timestamptz not null default now(),check(end_date is null or end_date>=start_date));
create table public.occupancies(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),room_id uuid not null references public.rooms(id),tenant_id uuid not null references public.tenants(id),agreement_id uuid references public.rental_agreements(id),check_in date not null,check_out date,notes text,check(check_out is null or check_out>=check_in));
create unique index one_open_occupancy_per_room on public.occupancies(room_id) where check_out is null;
create table public.additional_charges(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),property_id uuid references public.properties(id),room_id uuid references public.rooms(id),agreement_id uuid references public.rental_agreements(id),charge_name text not null,amount numeric(14,2) not null check(amount>=0),frequency text not null default 'monthly',is_active boolean not null default true);
create table public.invoices(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),invoice_number text not null,agreement_id uuid not null references public.rental_agreements(id),tenant_id uuid not null references public.tenants(id),room_id uuid not null references public.rooms(id),issue_date date not null default current_date,due_date date not null,subtotal numeric(14,2) not null default 0,total_amount numeric(14,2) not null check(total_amount>=0),paid_amount numeric(14,2) not null default 0 check(paid_amount>=0),status text not null default 'unpaid' check(status in('unpaid','partial','paid','overdue','cancelled')),notes text,unique(owner_id,invoice_number),check(paid_amount<=total_amount));
create table public.invoice_items(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),invoice_id uuid not null references public.invoices(id),description text not null,quantity numeric(12,2) not null default 1 check(quantity>0),unit_price numeric(14,2) not null default 0 check(unit_price>=0));
create table public.payments(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),tenant_id uuid not null references public.tenants(id),payment_date timestamptz not null default now(),amount numeric(14,2) not null check(amount>0),payment_method text not null default 'transfer',proof_path text,reference_number text,status text not null default 'pending' check(status in('pending','confirmed','rejected','reversed')),confirmed_at timestamptz,notes text,created_at timestamptz not null default now());
create table public.payment_allocations(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),payment_id uuid not null references public.payments(id),invoice_id uuid not null references public.invoices(id),amount numeric(14,2) not null check(amount>0),unique(payment_id,invoice_id));
create table public.reminder_logs(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),invoice_id uuid references public.invoices(id),tenant_id uuid not null references public.tenants(id),channel text not null default 'whatsapp',reminder_stage text not null,message_text text not null,status text not null default 'prepared',sent_at timestamptz);
create table public.transaction_categories(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),name text not null,transaction_type text not null check(transaction_type in('income','expense')),is_active boolean not null default true,unique(owner_id,name,transaction_type));
create table public.transactions(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),property_id uuid references public.properties(id),room_id uuid references public.rooms(id),category_id uuid references public.transaction_categories(id),payment_id uuid references public.payments(id),invoice_id uuid references public.invoices(id),transaction_date date not null default current_date,transaction_type text not null check(transaction_type in('income','expense')),amount numeric(14,2) not null check(amount>0),description text not null,reference_code text,status text not null default 'posted' check(status in('draft','posted','void')),reversal_of uuid references public.transactions(id));
create unique index one_posted_payment_transaction on public.transactions(payment_id) where payment_id is not null and status='posted' and transaction_type='income';
create table public.maintenance_requests(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),property_id uuid not null references public.properties(id),room_id uuid references public.rooms(id),title text not null,description text,priority text not null default 'normal',status text not null default 'reported',reported_at timestamptz not null default now(),completed_at timestamptz);
create table public.maintenance_updates(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),request_id uuid not null references public.maintenance_requests(id),update_note text not null,cost_amount numeric(14,2) not null default 0,vendor_name text,photo_path text,created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),title text not null,body text not null,notification_type text not null,read_at timestamptz);
create table public.activity_logs(id uuid primary key default gen_random_uuid(),owner_id uuid not null default auth.uid() references auth.users(id),entity_type text not null,entity_id uuid,action text not null,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
do $$ declare t text; begin foreach t in array array['profiles','properties','rooms','amenities','room_amenities','room_photos','tenants','tenant_documents','rental_agreements','occupancies','additional_charges','invoices','invoice_items','payments','payment_allocations','reminder_logs','transaction_categories','transactions','maintenance_requests','maintenance_updates','notifications','activity_logs'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "profiles owner only" on public.profiles for all to authenticated using(id=(select auth.uid())) with check(id=(select auth.uid()));
do $$ declare t text; begin foreach t in array array['properties','rooms','amenities','room_amenities','room_photos','tenants','tenant_documents','rental_agreements','occupancies','additional_charges','invoices','invoice_items','payments','payment_allocations','reminder_logs','transaction_categories','transactions','maintenance_requests','maintenance_updates','notifications','activity_logs'] loop execute format('create policy %I on public.%I for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()))',t||' owner only',t); end loop; end $$;
revoke all on all tables in schema public from anon;
grant usage on schema public to authenticated;
grant select,insert,update,delete on all tables in schema public to authenticated;
grant usage,select on all sequences in schema public to authenticated;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values
('tenant-documents','tenant-documents',false,10485760,array['image/jpeg','image/png','application/pdf']),
('room-photos','room-photos',false,10485760,array['image/jpeg','image/png','image/webp']),
('payment-proofs','payment-proofs',false,10485760,array['image/jpeg','image/png','application/pdf']),
('maintenance-photos','maintenance-photos',false,10485760,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy "owner read kos files" on storage.objects for select to authenticated using(bucket_id in('tenant-documents','room-photos','payment-proofs','maintenance-photos') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "owner upload kos files" on storage.objects for insert to authenticated with check(bucket_id in('tenant-documents','room-photos','payment-proofs','maintenance-photos') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "owner update kos files" on storage.objects for update to authenticated using(bucket_id in('tenant-documents','room-photos','payment-proofs','maintenance-photos') and (storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id in('tenant-documents','room-photos','payment-proofs','maintenance-photos') and (storage.foldername(name))[1]=(select auth.uid())::text);
create policy "owner delete kos files" on storage.objects for delete to authenticated using(bucket_id in('tenant-documents','room-photos','payment-proofs','maintenance-photos') and (storage.foldername(name))[1]=(select auth.uid())::text);
